"use client";

import { useCallback, useEffect, useId, useRef, useState, type ChangeEvent, type ComponentProps, type FocusEvent, type KeyboardEvent, type MouseEvent } from "react";

import { IconAlertCircle, IconClock } from "@rhs-ui/icons";
import { trackPress, whenReleased } from "@rhs-ui/primitives/time-estimate-field/blur-guard";
import {
  DEFAULT_LABELS,
  listUnits,
  readEstimate,
  UNIT_ORDER,
  writeHours,
  writeLong,
  writeShort,
  type EstimateLabels,
  type EstimateReading,
  type EstimateRules,
  type EstimateUnit,
} from "@rhs-ui/primitives/time-estimate-field/estimates";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@rhs-ui/primitives/input-group";
import { cn } from "@/lib/utils";

export type { EstimateLabels, EstimateUnit } from "@rhs-ui/primitives/time-estimate-field/estimates";

export interface TimeEstimateFieldProps extends Omit<ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "type" | "min" | "max" | "name" | "role" | "inputMode" | "children"> {
  /** The estimate in minutes, when you control it. Null while the field is empty. */
  value?: number | null;
  /** The estimate to start with, in minutes, when you do not control it. */
  defaultValue?: number | null;
  /**
   * Called with the estimate in minutes when the text is committed (Enter, or leaving the field), and with null when it was emptied or could not be read.
   * `valid` is true when there is a length inside `max`; one over it is still reported, so a form can say why.
   */
  onValueChange?: (minutes: number | null, state: { valid: boolean }) => void;
  /** How many hours a working day has: 1d is this many hours. Default 8. */
  hoursPerDay?: number;
  /** How many days a working week has: 1w is this many days. Default 5. */
  daysPerWeek?: number;
  /** The longest estimate allowed, in minutes. */
  max?: number;
  /** The units that may be typed and are written back: "w" for weeks, "d" for days, "h" and "m". Default all four. */
  units?: readonly EstimateUnit[];
  /** The field's name for a plain form submit: the estimate as whole minutes, or empty. */
  name?: string;
  /** The words the field says, for another language or your own voice. */
  labels?: Partial<EstimateLabels>;
}

// The group's own focus border would win over the red one while the cursor is still in a field that is wrong, so the red is asked for in the focused state too.
const WRONG = "border-destructive has-[input:focus-visible]:border-destructive has-[input:focus-visible]:ring-destructive/30";

/**
 * A duration you can type the way task trackers take it. "1h 30m", "90m",
 * "1.5h", "2:30" and "1d 2h" all work, and the length it was understood as is
 * written under the field ("1 h 30 min") before anything is committed, so a
 * wrong guess is seen while it is still cheap. A day is a working day (8 hours
 * unless `hoursPerDay` says otherwise) and a week a working week, and the line
 * says what the day was taken to be when one is used. Enter, or leaving the
 * field, rewrites the text in one form ("1h 30m"); Escape puts back the last
 * estimate. What cannot be read is answered with forms that would work, a unit
 * the field does not use is named, and a length over `max` is explained. It
 * reports minutes. One fast field where Duration input uses several number
 * boxes.
 */
export function TimeEstimateField({
  value,
  defaultValue = null,
  onValueChange,
  hoursPerDay = 8,
  daysPerWeek = 5,
  max,
  units = UNIT_ORDER,
  name,
  labels: labelOverrides,
  form,
  disabled,
  placeholder = "1h 30m",
  className,
  onBlur,
  onKeyDown,
  ref,
  "aria-describedby": describedBy,
  ...props
}: TimeEstimateFieldProps) {
  const base = useId();
  const noteId = `${base}-note`;
  const labels: EstimateLabels = { ...DEFAULT_LABELS, ...labelOverrides };
  const rules: EstimateRules = { hoursPerDay, daysPerWeek, units };
  const [own, setOwn] = useState<number | null>(defaultValue);
  const current = value === undefined ? own : value;
  const [draft, setDraft] = useState(() => (current === null ? "" : writeShort(current, rules)));
  const [synced, setSynced] = useState(value);
  const [error, setError] = useState<string | null>(null);
  const [said, setSaid] = useState("");
  const input = useRef<HTMLInputElement | null>(null);
  const reported = useRef<number | null | undefined>(undefined);
  const timer = useRef<number | undefined>(undefined);
  // The field keeps the ref you pass and uses its own to move the focus.
  const attach = useCallback(
    (node: HTMLInputElement | null) => {
      input.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  // An estimate that arrives from outside replaces what is typed; an echo of what was just reported changes nothing.
  if (value !== undefined && value !== synced) {
    setSynced(value);
    if (value !== reported.current) {
      setDraft(value === null ? "" : writeShort(value, rules));
      setError(null);
    }
  }

  useEffect(trackPress, []);
  useEffect(() => () => window.clearTimeout(timer.current), []);

  // What a screen reader was told stays only while it is news; left in the live region it would be read again together with the next message.
  useEffect(() => {
    if (!said) return;
    const clear = window.setTimeout(() => setSaid(""), 5000);
    return () => window.clearTimeout(clear);
  }, [said]);

  /** What is wrong with this reading, in words, or null. An empty field is not wrong: a form says what is required. */
  function problemOf(reading: EstimateReading): string | null {
    if (reading.kind === "format") return labels.unreadable(labels.examples);
    if (reading.kind === "unit") return labels.unusedUnit(labels.long[reading.unit], listUnits(rules, labels));
    if (reading.kind === "ok" && max !== undefined && reading.minutes > max) return labels.atMost(writeLong(max, rules, labels));
    return null;
  }

  function report(minutes: number | null, valid: boolean) {
    reported.current = minutes;
    if (value === undefined) setOwn(minutes);
    onValueChange?.(minutes, { valid });
  }

  const reading = readEstimate(draft, rules);
  const understood = reading.kind === "ok" ? reading : null;
  const days = understood?.units.some((unit) => unit === "d" || unit === "w") ?? false;

  function change(event: ChangeEvent<HTMLInputElement>) {
    const text = event.target.value;
    setDraft(text);
    window.clearTimeout(timer.current);
    setSaid("");
    // A message that is already showing follows the typing and goes as soon as the text is right. A new one waits for the field to be left.
    setError((showing) => (showing === null ? null : problemOf(readEstimate(text, rules))));
    const next = readEstimate(text, rules);
    if (next.kind === "ok") {
      const spoken = labels.said(writeLong(next.minutes, rules, labels));
      timer.current = window.setTimeout(() => setSaid(spoken), 700);
    }
  }

  /** The estimate is settled: written in one form, reported once, and any problem said in words. */
  function commit() {
    window.clearTimeout(timer.current);
    const settled = readEstimate(draft, rules);
    if (settled.kind === "empty") {
      setDraft("");
      if (current !== null) report(null, false);
      whenReleased(() => setError(null));
      return;
    }
    const problem = problemOf(settled);
    if (settled.kind !== "ok") {
      if (current !== null) report(null, false);
      whenReleased(() => setError(problem));
      return;
    }
    setDraft(writeShort(settled.minutes, rules));
    if (settled.minutes !== current || problem !== null) report(settled.minutes, problem === null);
    whenReleased(() => {
      setError(problem);
      if (problem) setSaid(problem);
    });
  }

  function leave(event: FocusEvent<HTMLInputElement>) {
    onBlur?.(event);
    commit();
  }

  function keyDown(event: KeyboardEvent<HTMLInputElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.nativeEvent.isComposing) return;
    if (event.key === "Enter") commit();
    else if (event.key === "Escape") {
      // Back to the last estimate, as when the field was entered.
      event.preventDefault();
      setDraft(current === null ? "" : writeShort(current, rules));
      setError(null);
    }
  }

  // The empty space in the field is part of the field: a click there puts the cursor in the text.
  function focusText(event: MouseEvent<HTMLDivElement>) {
    if (event.target !== input.current) input.current?.focus();
  }

  const invalid = error !== null;

  return (
    <div data-slot="time-estimate-field" className={cn("grid w-full min-w-0 grid-cols-1", className)}>
      <InputGroup onClick={focusText} className={cn("cursor-text", invalid && WRONG)}>
        <InputGroupAddon aria-hidden="true" className="pr-0">
          <IconClock />
        </InputGroupAddon>
        <InputGroupInput
          ref={attach}
          type="text"
          inputMode="text"
          enterKeyHint="done"
          autoComplete="off"
          autoCapitalize="off"
          autoCorrect="off"
          spellCheck={false}
          form={form}
          disabled={disabled}
          placeholder={placeholder}
          {...props}
          aria-label={props.id === undefined && props["aria-label"] === undefined && props["aria-labelledby"] === undefined ? labels.name : props["aria-label"]}
          aria-invalid={invalid || undefined}
          aria-describedby={[describedBy, noteId].filter(Boolean).join(" ")}
          value={draft}
          onChange={change}
          onBlur={leave}
          onKeyDown={keyDown}
          className="pl-2 tabular-nums"
        />
      </InputGroup>
      <div id={noteId} className="mt-1.5 min-h-5 text-xs">
        <div aria-live="polite">
          {error ? (
            <p className="flex items-start gap-1.5 text-destructive">
              <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
              {error}
            </p>
          ) : null}
        </div>
        {error ? null : understood ? (
          <p className={cn("flex flex-wrap items-baseline gap-x-2 gap-y-0.5 text-muted-foreground tabular-nums", disabled && "opacity-50")}>
            <span className="font-medium text-foreground">{writeLong(understood.minutes, rules, labels)}</span>
            {days && units.includes("h") ? (
              <span>
                {writeHours(understood.minutes, labels)}, {labels.day(`${hoursPerDay} ${labels.short.h}`)}
              </span>
            ) : null}
          </p>
        ) : (
          <p className={cn("text-muted-foreground", disabled && "opacity-50")}>{labels.hint}</p>
        )}
      </div>
      <span role="status" className="sr-only">
        {said}
      </span>
      {name ? <input type="hidden" name={name} form={form} value={current === null ? "" : String(current)} disabled={disabled} /> : null}
    </div>
  );
}

/** The four units of an estimate, from the biggest to the smallest: weeks, days, hours and minutes. */
export type EstimateUnit = "w" | "d" | "h" | "m";

/** The order of the units, biggest first. */
export const UNIT_ORDER: readonly EstimateUnit[] = ["w", "d", "h", "m"];

/** What a working day and week are, and which units are used. */
export interface EstimateRules {
  /** Hours in a working day: 1d is this many hours. */
  hoursPerDay: number;
  /** Days in a working week: 1w is this many days. */
  daysPerWeek: number;
  /** The units that may be typed and are written back. */
  units: readonly EstimateUnit[];
}

/** The words the field says, in the line under it and to a screen reader. Each can be replaced, for another language or your own voice. */
export interface EstimateLabels {
  /** The name of the field for a screen reader when it has no label, id or aria-label of its own. */
  name: string;
  /** What the line under the field says while nothing is typed. */
  hint: string;
  /** The forms that are understood, in the sentence below. */
  examples: string;
  /** Said when the text is not a duration. `examples` are forms that would work. */
  unreadable: (examples: string) => string;
  /** Said when a unit was typed that this field does not use. `unit` is its name, `allowed` the ones that are used. */
  unusedUnit: (unit: string, allowed: string) => string;
  /** The estimate is longer than `max`. `limit` is that length, written out. */
  atMost: (limit: string) => string;
  /** What a screen reader hears once the typing pauses. */
  said: (text: string) => string;
  /** What a working day and week are, shown beside an estimate that uses them: "1 d = 8 h". */
  day: (hours: string) => string;
  week: (days: string) => string;
  /** The short names of the units as they are written in the line under the field: "w", "d", "h", "min". */
  short: Readonly<Record<EstimateUnit, string>>;
  /** The names of the units for a message, plural: "weeks", "days", "hours", "minutes". */
  long: Readonly<Record<EstimateUnit, string>>;
}

export const DEFAULT_LABELS: EstimateLabels = {
  name: "Estimate",
  hint: "Try 1h 30m, 90m, 1.5h or 2:30.",
  examples: "1h 30m, 90m, 1.5h or 2:30",
  unreadable: (examples) => `That is not a time I can read. Try ${examples}.`,
  unusedUnit: (unit, allowed) => `This estimate does not use ${unit}. Use ${allowed}.`,
  atMost: (limit) => `Estimates go up to ${limit}.`,
  said: (text) => `Understood as ${text}`,
  day: (hours) => `1 d = ${hours}`,
  week: (days) => `1 w = ${days}`,
  short: { w: "w", d: "d", h: "h", m: "min" },
  long: { w: "weeks", d: "days", h: "hours", m: "minutes" },
};

export const DEFAULT_RULES: EstimateRules = { hoursPerDay: 8, daysPerWeek: 5, units: UNIT_ORDER };

const WORDS: Readonly<Record<string, EstimateUnit>> = {
  w: "w",
  wk: "w",
  wks: "w",
  week: "w",
  weeks: "w",
  d: "d",
  day: "d",
  days: "d",
  h: "h",
  hr: "h",
  hrs: "h",
  hour: "h",
  hours: "h",
  m: "m",
  min: "m",
  mins: "m",
  minute: "m",
  minutes: "m",
};

/** How many minutes one of each unit is, for these rules. A day is a working day and a week a working week, as in a task tracker. */
export function minutesPerUnit(rules: EstimateRules): Record<EstimateUnit, number> {
  const day = rules.hoursPerDay * 60;
  return { m: 1, h: 60, d: day, w: day * rules.daysPerWeek };
}

/**
 * Digits typed on a keyboard that writes them differently (Arabic-Indic,
 * Persian) as the digits 0 to 9, and the full-width colon and other spaces as
 * plain ones. Written by code point, so the source stays ASCII.
 */
function asciiText(text: string): string {
  let plain = "";
  for (const char of text) {
    const code = char.charCodeAt(0);
    if (code >= 0x660 && code <= 0x669) plain += String(code - 0x660);
    else if (code >= 0x6f0 && code <= 0x6f9) plain += String(code - 0x6f0);
    else if (code === 0x66b) plain += ".";
    else if (code === 0xff1a) plain += ":";
    else if (code === 0xa0 || code === 0x202f) plain += " ";
    else plain += char;
  }
  return plain;
}

/** What the text came to: nothing at all, a length, a unit this field does not use, or something that is not a duration. */
export type EstimateReading = { kind: "empty" } | { kind: "ok"; minutes: number; units: readonly EstimateUnit[] } | { kind: "unit"; unit: EstimateUnit } | { kind: "format" };

const TOKEN = /\s*(\d+(?:\.\d+)?|\.\d+)\s*([a-z]*)\s*/y;

/**
 * A length of time as minutes. It reads mixed forms with weeks, days, hours and
 * minutes ("1w 2d", "1d 2h 30m", "1h, 30m", "1 hour and 30 minutes"), decimals
 * ("1.5h", "1,5h": half a day is 4 hours with a working day of 8), a clock
 * ("2:30" is two and a half hours), and a number after a unit that stands for
 * the next smaller one ("1h30" is 1h 30m). A bare whole number is minutes and a
 * bare decimal is hours, so "90" and "1.5" both read as an hour and a half.
 * Everything is worked out on the digits, and the result is rounded to a whole
 * minute (or to the smallest unit the field uses).
 */
export function readEstimate(raw: string, rules: EstimateRules): EstimateReading {
  const text = asciiText(raw).toLowerCase().trim();
  if (!text) return { kind: "empty" };
  const per = minutesPerUnit(rules);
  const allowed = new Set(rules.units);
  const smallest = [...UNIT_ORDER].reverse().find((unit) => allowed.has(unit)) ?? "m";
  const clock = /^(\d+):(\d{1,2})$/.exec(text);
  if (clock) {
    const minutes = Number(clock[2]);
    if (minutes > 59 || !allowed.has("h")) return { kind: "format" };
    return { kind: "ok", minutes: roundToUnit(Number(clock[1]) * 60 + minutes, per[smallest]), units: ["h", "m"] };
  }
  // A comma between digits is a decimal sign, any other comma, an "and" or an ampersand only separates.
  const tidy = text.replace(/(\d),(\d)/g, "$1.$2").replace(/\band\b|[,&+]/g, " ");
  let total = 0;
  let last: EstimateUnit | null = null;
  const used: EstimateUnit[] = [];
  let at = 0;
  while (at < tidy.length) {
    TOKEN.lastIndex = at;
    const match = TOKEN.exec(tidy);
    if (!match) return { kind: "format" };
    at = TOKEN.lastIndex;
    const amount = Number(match[1]);
    const word = match[2] ?? "";
    let unit: EstimateUnit | undefined;
    if (word) unit = WORDS[word];
    else if (last === null) unit = (match[1] ?? "").includes(".") && allowed.has("h") ? "h" : smallest;
    else unit = UNIT_ORDER[UNIT_ORDER.indexOf(last) + 1];
    if (!unit || !Number.isFinite(amount)) return { kind: "format" };
    // A number after a unit is the next smaller one, so that unit has to be one this field uses: "1h30" needs minutes.
    if (!allowed.has(unit)) return word ? { kind: "unit", unit } : { kind: "format" };
    total += amount * per[unit];
    last = unit;
    used.push(unit);
  }
  if (!used.length || !Number.isFinite(total)) return { kind: "format" };
  return { kind: "ok", minutes: roundToUnit(total, per[smallest]), units: used };
}

/** A length rounded to a whole number of the smallest unit in use, half up. */
const roundToUnit = (minutes: number, unit: number): number => Math.round(Math.round(minutes * 1000) / 1000 / unit) * unit;

/** A length split into the units in use, biggest first, with the units that came to nothing left out. A length of nothing is "0" of the smallest unit. */
export function splitEstimate(minutes: number, rules: EstimateRules): { unit: EstimateUnit; value: number }[] {
  const per = minutesPerUnit(rules);
  const used = UNIT_ORDER.filter((unit) => rules.units.includes(unit));
  const parts: { unit: EstimateUnit; value: number }[] = [];
  let rest = Math.round(minutes);
  for (const unit of used) {
    const value = Math.floor(rest / per[unit]);
    rest -= value * per[unit];
    if (value > 0) parts.push({ unit, value });
  }
  if (!parts.length) parts.push({ unit: used[used.length - 1] ?? "m", value: 0 });
  return parts;
}

/** The estimate as it is typed and written back to the field: "1w 2d 3h 30m". */
export function writeShort(minutes: number, rules: EstimateRules): string {
  return splitEstimate(minutes, rules)
    .map((part) => `${part.value}${part.unit}`)
    .join(" ");
}

/** The estimate for the line under the field: "1 h 30 min". */
export function writeLong(minutes: number, rules: EstimateRules, labels: EstimateLabels): string {
  return splitEstimate(minutes, rules)
    .map((part) => `${part.value} ${labels.short[part.unit]}`)
    .join(" ");
}

/** The whole estimate in hours and minutes, for an estimate that is counted in days or weeks: "10 h", "41 h 30 min". */
export function writeHours(minutes: number, labels: EstimateLabels): string {
  const hours = Math.floor(minutes / 60);
  const rest = Math.round(minutes - hours * 60);
  return rest ? `${hours} ${labels.short.h} ${rest} ${labels.short.m}` : `${hours} ${labels.short.h}`;
}

/** The units that are in use, written as a list for a message: "days, hours and minutes". */
export function listUnits(rules: EstimateRules, labels: EstimateLabels): string {
  const names = UNIT_ORDER.filter((unit) => rules.units.includes(unit)).map((unit) => labels.long[unit]);
  return names.length > 1 ? `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}` : (names[0] ?? "");
}

// A message that appears while a finger or a mouse button is still down moves the next control from under the pointer and swallows its click (the usual way
// a blur check eats a submit), so such a message waits until the press is over.
//
// A mouse press moves the focus while the button is down. A touch tap does not: it runs pointerdown, touchstart, pointerup, touchend, and only then the mouse
// events the browser makes up (mousedown, which moves the focus and blurs the field, then mouseup and click). So a press is armed by pointerdown, mousedown and
// touchstart alike, and a release only counts when no newer press began after it was announced.

/** A press that began longer ago than this is taken to be stuck (its release never arrived), not to be the one that blurred the field. */
const STALE_MS = 3000;

let pressed = false;
let pressedAt = 0;
let presses = 0;
let tracking = false;
const afterRelease: (() => void)[] = [];

/** Starts watching presses for the whole page, once. Call it from an effect. */
export function trackPress(): void {
  if (tracking) return;
  tracking = true;
  const press = () => {
    pressed = true;
    pressedAt = performance.now();
    presses += 1;
  };
  const release = () => {
    const seen = presses;
    window.setTimeout(() => {
      // Touch makes its mouse events after it has released: a press that began since then is still going on.
      if (seen !== presses) return;
      pressed = false;
      for (const run of afterRelease.splice(0)) run();
    }, 0);
  };
  // Passive: these only watch, and a touch listener that could cancel would hold the page's scrolling back.
  const options = { capture: true, passive: true };
  for (const type of ["pointerdown", "mousedown", "touchstart"] as const) document.addEventListener(type, press, options);
  for (const type of ["pointerup", "pointercancel", "mouseup", "touchend", "touchcancel", "click"] as const) document.addEventListener(type, release, options);
}

/** Runs `run` now, or, while a press is going on, as soon as it is over. */
export function whenReleased(run: () => void): void {
  if (pressed && performance.now() - pressedAt < STALE_MS) afterRelease.push(run);
  else run();
}
